from pathlib import Path
from hashlib import sha256
site = Path('products/sites/shopify-catalogue-example')
for path in sorted(site.rglob('*')):
    if not path.is_file():
        continue
    data = path.read_bytes()
    print(path, len(data), sha256(data).hexdigest())
    if path.name in {'transform.py', 'verify_example.py'}:
        lines = data.decode('utf-8').splitlines()
        start = next((i for i, line in enumerate(lines) if line.startswith('def main(')), None)
        if start is not None:
            print('\n'.join(lines[start:start + 45]))
for number, line in enumerate((site / 'index.html').read_text(encoding='utf-8').splitlines(), 1):
    if 'python' in line.lower() and ('.py' in line or 'command' in line.lower()):
        print(f'{number}: {line[:500]}')
